import Foundation
public import NostrCore

/// A parsed NIP-47 `nostr+walletconnect://` connection string.
///
/// The wallet service issues this URI to authorize a client. It carries everything the client needs
/// to talk to the wallet:
///
/// ```text
/// nostr+walletconnect://<wallet-public-key-hex>?relay=<wss url>&secret=<32-byte hex>&lud16=<address>
/// ```
///
/// - The host is the wallet service's public key in canonical lowercase hex.
/// - `relay` is the relay the wallet listens on; it may appear more than once.
/// - `secret` is a 32-byte private key generated by the wallet for **this client**. The client
///   signs its request events and encrypts their payloads with it, so the user's main Nostr key is
///   never exposed (see ``clientKeyPair``).
/// - `lud16` is an optional lightning address the client can use to set up payments.
///
/// https://github.com/nostr-protocol/nips/blob/master/47.md
public struct WalletConnectURI: Sendable, Hashable {
    /// The wallet service's public key.
    public let walletPublicKey: PublicKey

    /// The relays the wallet service listens on. Always at least one.
    public let relays: [RelayURL]

    /// The client secret key. The client signs and encrypts with this key.
    public let secret: PrivateKey

    /// An optional lightning address (lud16) the wallet advertised.
    public let lud16: String?

    /// The client identity derived from ``secret`` at initialization. Cached so signing and
    /// encryption never repeat the EC point multiplication. It is fully determined by ``secret``,
    /// so it is excluded from `Equatable`/`Hashable`.
    private let cachedClientKeyPair: KeyPair

    /// The URI scheme, without the `://` separator.
    public static let scheme = "nostr+walletconnect"

    /// Creates a connection from its components, validating the relay list.
    ///
    /// - Parameters:
    ///   - walletPublicKey: The wallet service's public key.
    ///   - relays: The relays the wallet listens on (must contain at least one).
    ///   - secret: The client secret key.
    ///   - lud16: An optional lightning address.
    /// - Throws: ``WalletConnectError/invalidURI(reason:)`` if `relays` is empty.
    public init(
        walletPublicKey: PublicKey, relays: [RelayURL], secret: PrivateKey, lud16: String? = nil
    ) throws(WalletConnectError) {
        guard !relays.isEmpty else {
            throw WalletConnectError.invalidURI(reason: "at least one relay is required")
        }

        self.walletPublicKey = walletPublicKey
        self.relays = relays
        self.secret = secret
        self.lud16 = lud16
        // Derived once so later signing/encryption never repeats the point multiplication.
        self.cachedClientKeyPair = KeyPair(privateKey: secret)
    }

    /// Parses a `nostr+walletconnect://` connection string.
    ///
    /// - Parameter string: The connection string issued by the wallet service.
    /// - Throws: ``WalletConnectError/invalidURI(reason:)`` if the string is malformed or missing
    ///   required fields, including a host that is not a canonical lowercase hex public key, a
    ///   `relay` value that is not a valid relay URL, or a `secret` that is not a valid private key.
    public init(string: String) throws(WalletConnectError) {
        guard let components = URLComponents(string: string),
            components.scheme?.lowercased() == Self.scheme
        else {
            throw WalletConnectError.invalidURI(reason: "scheme must be \(Self.scheme)://")
        }

        guard let host = components.host, !host.isEmpty else {
            throw WalletConnectError.invalidURI(reason: "missing wallet public key")
        }
        guard let walletPublicKey = PublicKey(host) else {
            throw WalletConnectError.invalidURI(reason: "wallet public key must be lowercase 32-byte hex")
        }

        let queryItems = components.queryItems ?? []

        let relayValues = queryItems.filter { $0.name == "relay" }.compactMap { $0.value }
        // Every relay must parse: dropping a malformed one would make the URI look like it lists
        // fewer relays than it does.
        let relays = relayValues.compactMap(RelayURL.init)
        guard !relayValues.isEmpty, relays.count == relayValues.count else {
            throw WalletConnectError.invalidURI(reason: "missing or malformed relay")
        }

        guard let secretHex = queryItems.first(where: { $0.name == "secret" })?.value,
            let secret = try? PrivateKey(hex: secretHex)
        else {
            throw WalletConnectError.invalidURI(reason: "missing or malformed secret")
        }

        let lud16 = queryItems.first(where: { $0.name == "lud16" })?.value

        try self.init(walletPublicKey: walletPublicKey, relays: relays, secret: secret, lud16: lud16)
    }

    /// The connection string, with each relay percent-encoded as a `relay` query parameter.
    public var stringValue: String {
        var components = URLComponents()
        components.scheme = Self.scheme
        components.host = walletPublicKey.hex

        var items = relays.map { URLQueryItem(name: "relay", value: $0.description) }
        items.append(URLQueryItem(name: "secret", value: secret.hex))
        if let lud16 {
            items.append(URLQueryItem(name: "lud16", value: lud16))
        }
        components.queryItems = items

        // Unreachable for a validated URI (constant scheme, hex host, URL relays); fail loud rather
        // than emit a silently broken connection string if that invariant is ever violated.
        guard let string = components.string else {
            fatalError("URLComponents failed to serialize a validated NWC URI")
        }
        return string
    }

    /// The client identity derived from ``secret`` — used to sign requests and encrypt payloads.
    public var clientKeyPair: KeyPair {
        cachedClientKeyPair
    }

    /// A signer for the client identity. Convenience over ``clientKeyPair``.
    public var clientSigner: EventSigner {
        EventSigner(keyPair: cachedClientKeyPair)
    }

    /// The client's public key, derived from ``secret``.
    public var clientPublicKey: PublicKey {
        cachedClientKeyPair.publicKey
    }
}

// MARK: - Equatable & Hashable

extension WalletConnectURI {
    public static func == (lhs: WalletConnectURI, rhs: WalletConnectURI) -> Bool {
        lhs.walletPublicKey == rhs.walletPublicKey
            && lhs.relays == rhs.relays
            && lhs.secret == rhs.secret
            && lhs.lud16 == rhs.lud16
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(walletPublicKey)
        hasher.combine(relays)
        hasher.combine(secret)
        hasher.combine(lud16)
    }
}
